update.foreach:
UPDATE mp_devops_load_scene_result_log


        result_log = #{item.resultLog},


        result_status = #{item.resultStatus},

    update_time = now()

WHERE pk = (
    SELECT pk
    FROM mp_devops_load_scene_result_log


            AND task_id = #{item.taskId}


            AND instance_id = #{item.instanceId}


    ORDER BY create_time DESC
    LIMIT 1
);

mapper.delete:
delete from mp_devops_load
and id not in
#{item}

mapper.select:
SELECT
*
FROM
mp_devops_load


        and pk = #{param.pk}


        and pk in

            #{item}



        and id = #{param.id}


        and id in

            #{item}



        and tool_name like concat('%', #{param.toolName}, '%')


        and action_type like concat('%', #{param.actionType}, '%')


        and run_table = #{param.runTable}


        and source = #{param.source}


        and control_type = #{param.controlType}


        and vulne_code in

            #{vulneCode}



        and technology = #{param.technology}


order by create_time desc

    limit #{param.offset}, #{param.pageSize}

SELECT
log.*,
mdl.tool_name,
mdl.tool_description,
mdl.action_type,
mdl.run_table,
mdl.control_type
FROM
mp_devops_load_scene_result_log log
inner join
mp_devops_load mdl
on log.id = mdl.id


        and mdl.pk = #{param.pk}


        and mdl.pk in

            #{item}



        and log.scene_id = #{param.sceneId}


        and log.create_time >= #{param.beginTime, jdbcType=TIMESTAMP}


        and log.create_time <= #{param.overTime, jdbcType=TIMESTAMP}


order by log.create_time desc

    limit #{param.offset}, #{param.pageSize}

SELECT
count(0)
FROM
mp_devops_load_scene_result_log log
inner join
mp_devops_load mdl
on log.id = mdl.id


        and mdl.pk = #{param.pk}


        and mdl.pk in

            #{item}



        and log.scene_id = #{param.sceneId}


        and log.create_time >= #{param.beginTime, jdbcType=TIMESTAMP}


        and log.create_time <= #{param.overTime, jdbcType=TIMESTAMP}

